    iron_glassgloryhole = { name = "Železni ognjena komora za oblikovanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ognjena komora za oblikovanje za steklarje." },
    bronze_glassgloryhole = { name = "Bronast ognjena komora za oblikovanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ognjena komora za oblikovanje za steklarje." },
